-- V1.2.0 CDU17 (Iter2/CFG-02): usuarios locales con hash BCrypt y bloqueo por intentos.
-- El esquema sigue siendo autoritativo (spring.jpa.hibernate.ddl-auto = none).
-- Variante MySQL (D34): GENERATED BY DEFAULT AS IDENTITY -> AUTO_INCREMENT y
-- TIMESTAMP(6) WITH TIME ZONE -> DATETIME(6) (la conexion JDBC fuerza UTC).

CREATE TABLE seguridad_usuario (
    id                BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    usuario           VARCHAR(60)  NOT NULL,
    password_hash     VARCHAR(100) NOT NULL,
    rol               VARCHAR(20)  NOT NULL,
    activo            BOOLEAN      NOT NULL,
    intentos_fallidos INTEGER      NOT NULL,
    bloqueado_hasta   DATETIME(6),
    CONSTRAINT uk_seguridad_usuario_usuario UNIQUE (usuario)
);

-- Datos semilla de DESARROLLO (no son secretos de produccion): las contrasenas en claro
-- van documentadas para poder probar el sistema en local y en los tests de humo del
-- servidor. password_hash es BCrypt (coste por defecto) de esa contrasena. La cuenta
-- 'bloqueable' existe solo para verificar por API el bloqueo por intentos fallidos.
-- admin=iso2-admin  medico=iso2-medico  tecnico=iso2-tecnico  celador=iso2-ses
-- recepcionista=iso2-rec  bloqueable=iso2-bloq
